"""Research writer regressions: generated bytes, CLI streams and report preservation."""
from __future__ import annotations

import io
import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "spec/tools"))
import build_catalog
import text_output
import validate


class ResearchWriters(unittest.TestCase):
    def test_generated_file_is_utf8_lf_without_bom(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "output.md"
            text_output.write_utf8_lf(path, "Žluťoučký\r\nsecond\rthird\n")
            self.assertEqual(path.read_bytes(), "Žluťoučký\nsecond\nthird\n".encode("utf-8"))

    def test_cli_streams_override_windows_newline_and_legacy_encoding(self):
        output, errors = io.BytesIO(), io.BytesIO()
        stdout = io.TextIOWrapper(output, encoding="ascii", newline="\r\n")
        stderr = io.TextIOWrapper(errors, encoding="ascii", newline="\r\n")
        with patch.object(sys, "stdout", stdout), patch.object(sys, "stderr", stderr):
            text_output.configure_output()
            print("Žluťoučký")
            print("Příliš", file=sys.stderr)
            stdout.flush()
            stderr.flush()
        self.assertEqual(output.getvalue(), "Žluťoučký\n".encode("utf-8"))
        self.assertEqual(errors.getvalue(), "Příliš\n".encode("utf-8"))

    def test_catalog_writes_lf_and_preserves_authored_report(self):
        with tempfile.TemporaryDirectory() as directory:
            base = Path(directory)
            for name in ("data", "projects", "categories"):
                (base / name).mkdir()
            row = {
                "id": "ai-skills--fixture", "name": "fixture", "category": "ai-skills",
                "github": "https://example.invalid/fixture", "revision": "a" * 40,
                "commit_date": "2026-10-28T00:00:00Z", "file_count": 1, "readme": "README.md",
                "screening_excerpt": "Žluťoučký fixture", "manifests": [],
                "license_files": [], "license_hint": "unverified", "topics": ["skills"],
                "report": "projects/ai-skills--fixture.md",
            }
            text_output.write_utf8_lf(base / "data/inventory.json", json.dumps([row, {**row, "id": "ai-skills--retained", "report": "projects/retained.md"}]))
            text_output.write_utf8_lf(base / "README.md", "# Index\n<!-- categories:start -->\n<!-- categories:end -->\n")
            text_output.write_utf8_lf(base / "skills.md", "# Skills\n\nAuthored context.\n")
            authored = base / "projects/retained.md"
            authored.write_bytes(b"# Author-owned report\n")
            with patch.object(build_catalog, "BASE", base), patch.object(build_catalog, "configure_output"):
                with patch.object(sys, "stdout", io.StringIO()):
                    build_catalog.main()
            for path in base.rglob("*"):
                if path.is_file():
                    self.assertNotIn(b"\r", path.read_bytes(), str(path))
            self.assertIn("Žluťoučký fixture", (base / row["report"]).read_text(encoding="utf-8"))
            self.assertEqual(authored.read_bytes(), b"# Author-owned report\n")
            self.assertIn("Authored context.", (base / "skills.md").read_text(encoding="utf-8"))

    def test_validator_file_and_stdout_use_identical_json_data(self):
        with tempfile.TemporaryDirectory() as directory:
            output = io.BytesIO()
            stdout = io.TextIOWrapper(output, encoding="ascii", newline="\r\n")
            result = {"issues": [], "label": "Žluťoučký", "blobs": []}
            with patch.object(validate, "validate", return_value=result):
                with patch.object(sys, "argv", ["validate", "--root", directory]), patch.object(sys, "stdout", stdout):
                    with self.assertRaises(SystemExit) as completed:
                        validate.main()
                    self.assertEqual(completed.exception.code, False)
                    stdout.flush()
            data = (Path(directory) / "spec/analyses/validation.json").read_bytes()
            self.assertNotIn(b"\r", data)
            self.assertEqual(json.loads(data), result)
            self.assertNotIn(b"\r", output.getvalue())
            self.assertEqual(json.loads(output.getvalue()), {"issues": [], "label": "Žluťoučký"})


if __name__ == "__main__":
    text_output.configure_output()
    unittest.main()
